sys_script_include.script:
var AttachmentUtils = Class.create();
AttachmentUtils.prototype = {
    initialize: function() {},

    getAttachmentCount: function(tableName, tableSysId) {
        var total_attachments = 0;
        var gr_agg = new GlideAggregate("sys_attachment");
        gr_agg.addQuery("table_name", tableName);
        gr_agg.addQuery("table_sys_id", tableSysId);
		gr_agg.addAggregate("COUNT");
        gr_agg.query();
        gr_agg.next();
        total_attachments = parseInt(gr_agg.getAggregate("COUNT"), 10);
        return total_attachments;
    },

	// Return:
	// [{ sysId, tableName, tableSysId }, ... ]
	get:function(tableName, tableSysId) {
		var objects = [];
		var gr = new GlideRecord("sys_attachment");
		gr.addQuery("table_name", tableName );
		gr.addQuery("table_sys_id", tableSysId );
		gr.query();
		while(gr.hasNext()) {
			gr.next();
			objects.push({
				"sysId":gr.getValue("sys_id"),
				"tableName":tableName,
				"tableSysId":tableSysId
			});
		}
		return objects;
	},


    // objects: array representing existing attachments. Not a GlideRecord.
	// toTableName: Table to shift these attachments to.
	// toTableSysId: Record to shift these attachments to.
	// dropOriginal: delete the originals
    shift: function(objects, toTableName, toTableSysId, dropOriginal = true) {
		var new_attachment_sys_ids = [];
        var gsa = new GlideSysAttachment();
        objects.forEach(function(e) {

            // original
            var gr_attachment = new GlideRecord("sys_attachment");
            gr_attachment.get(e.sysId);

			//copy to
            var gr_target = new GlideRecord(toTableName);
            gr_target.get(toTableSysId);
            var new_attachment_sys_id = gsa.writeContentStream(
                gr_target,
                gr_attachment.getValue('file_name'),
                gr_attachment.getValue('content_type'),
                gsa.getContentStream(e.sysId)
            );
			new_attachment_sys_ids.push(new_attachment_sys_id);
        });

        if (dropOriginal) {
            objects.forEach(function(e) {
                gsa.deleteAttachment(e.sysId);
            });
        }
		return new_attachment_sys_ids;
    },


    type: 'AttachmentUtils'
};
